using NUnit.Framework; using SmallWorld.Save.Stage10; using SmallWorld.Save.Stage12;
namespace SmallWorld.Tests.EditMode.Save.Stage12 { public sealed class MemorySpaceProgressTests { static MemorySpaceDefinition D=>new MemorySpaceDefinition{Id="memory.midnight",EntrySceneId="03_MemoryMidnight",SafeZoneId="safe"}; [Test] public void EnterReachSafeZoneExit_Persists(){var save=SaveData.CreateNew();var f=new MemorySpaceFlow();var p=new MemorySpaceProgress();var s=f.Enter(D,null);f.ReachSafeZone(D,s);f.Exit(D,s);p.Set(save,s);var r=p.Get(save,D.Id);Assert.That(r.HasEntered,Is.True);Assert.That(r.HasExited,Is.True);Assert.That(r.SafeZoneReached,Is.True);Assert.That(r.VisitCount,Is.EqualTo(1));Assert.That(r.Phase,Is.EqualTo(MemorySpacePhase.WhiteRoom));} [Test] public void CannotExitBeforeEntering(){Assert.Throws<System.InvalidOperationException>(()=>new MemorySpaceFlow().Exit(D,new MemorySpaceState{SpaceId=D.Id}));} [Test] public void ReenterIncrementsVisitOnlyAfterExit(){var f=new MemorySpaceFlow();var s=f.Enter(D,null);f.Enter(D,s);Assert.That(s.VisitCount,Is.EqualTo(1));f.Exit(D,s);f.Enter(D,s);Assert.That(s.VisitCount,Is.EqualTo(2));} } }
